91:/** Writes the setup's rules into the sandbox and commits it as `setup:`. Returns the setup commit. */
92:export function swapRules(sandboxPath: string, rulesFile: string | string[]): string {
93:  const files = Array.isArray(rulesFile) ? rulesFile : [rulesFile];
94:  const text = files.map((f) => readFileSync(f, "utf8")).join("\n");
95:  writeFileSync(join(sandboxPath, RULES_NAME), text);
96:  gitOk(sandboxPath, ["add", "-f", "--", RULES_NAME]);
97:  gitOk(sandboxPath, ["commit", "-q", "--allow-empty", "-m", `setup: ${RULES_NAME} from ${files.join(" + ")}`]);
98:  return gitOk(sandboxPath, ["rev-parse", "HEAD"]).trim();
99:}
