101:/** Stages everything the agent did and writes `git diff --binary` against the setup commit. */
102:export function captureDiff(sandboxPath: string, setupSha: string, outDir: string): HarnessDiff {
103:  gitOk(sandboxPath, ["add", "-A"]);
104:  const patchPath = join(outDir, "agent.patch");
105:  writeFileSync(patchPath, gitOk(sandboxPath, ["diff", "--cached", "--binary", setupSha]));
106:  const rows = gitOk(sandboxPath, ["diff", "--cached", "--numstat", setupSha])
107:    .split("\n")
108:    .filter(Boolean)
109:    .map((l) => l.split("\t"));
110:  return {
111:    patchPath,
112:    filesChanged: rows.length,
113:    added: rows.reduce((s, r) => s + (Number(r[0]) || 0), 0),
114:    removed: rows.reduce((s, r) => s + (Number(r[1]) || 0), 0),
115:    files: rows.map((r) => r[2] ?? ""),
116:  };
117:}
