119:/** Throws away a failed attempt's partial work so a retry starts from the setup commit. */
120:function resetTo(sandboxPath: string, setupSha: string): void {
121:  gitOk(sandboxPath, ["reset", "-q", "--hard", setupSha]);
122:  gitOk(sandboxPath, ["clean", "-qfdx"]);
123:}
