125:// ---------- process ----------
126:interface Exec {
127:  code: number | null;
128:  out: string;
129:  err: string;
130:  timedOut: boolean;
131:  wallMs: number;
132:  spawnError: string | null;
133:}
134:
135:/** Runs in its own process group so a timeout kills the agent's tool subprocesses too. */
136:function exec(bin: string, args: string[], cwd: string, env: Record<string, string>, timeoutMs: number): Promise<Exec> {
137:  const t0 = performance.now();
138:  return new Promise((done) => {
139:    const out: Buffer[] = [];
140:    const err: Buffer[] = [];
141:    let timedOut = false;
142:    let spawnError: string | null = null;
143:    const p = spawn(bin, args, { cwd, env, detached: true, stdio: ["ignore", "pipe", "pipe"] });
144:    const kill = () => {
145:      try {
146:        if (p.pid) process.kill(-p.pid, "SIGKILL");
147:      } catch {
148:        p.kill("SIGKILL");
149:      }
150:    };
151:    const timer = setTimeout(() => {
152:      timedOut = true;
153:      kill();
154:    }, timeoutMs);
155:    p.stdout?.on("data", (b: Buffer) => out.push(b));
156:    p.stderr?.on("data", (b: Buffer) => err.push(b));
157:    p.on("error", (e) => {
158:      spawnError = String(e);
159:    });
160:    p.on("close", (code) => {
161:      clearTimeout(timer);
162:      if (timedOut) kill(); // stragglers that kept the pipes open
163:      done({
164:        code,
165:        out: Buffer.concat(out).toString(),
166:        err: Buffer.concat(err).toString(),
167:        timedOut,
168:        wallMs: Math.round(performance.now() - t0),
169:        spawnError,
170:      });
171:    });
172:  });
173:}
