175:// ---------- parsing ----------
176:type Json = Record<string, any>;
177:
178:export function parseResult(stdout: string): Json | null {
179:  const lines = stdout.trim().split("\n").filter(Boolean);
180:  for (let i = lines.length - 1; i >= 0; i--) {
181:    try {
182:      const j = JSON.parse(lines[i] ?? "");
183:      if (j && typeof j === "object" && !Array.isArray(j)) return j;
184:    } catch {}
185:  }
186:  try {
187:    const j = JSON.parse(stdout);
188:    return j && typeof j === "object" && !Array.isArray(j) ? j : null;
189:  } catch {
190:    return null;
191:  }
192:}
193:
194:/** HTTP status of an API failure, from the result text or stderr ("API Error: 529 ..."). */
195:export function apiStatusOf(j: Json | null, stderr: string): number | null {
196:  if (typeof j?.api_error_status === "number") return j.api_error_status;
197:  const text = `${typeof j?.result === "string" ? j.result : ""}\n${stderr}`;
198:  const m = text.match(/API Error:?\s*(\d{3})\b/i) ?? text.match(/\b(429|5\d\d)\b[^\n]*(rate.?limit|overloaded|server|unavailable|timeout)/i);
199:  return m ? Number(m[1]) : null;
200:}
201:
202:const retryable = (s: number | null) => s !== null && (s === 429 || (s >= 500 && s <= 599));
203:
204:const PROVIDER_STATUSES = new Set([401, 402, 403]);
205:const PROVIDER_MESSAGE = /insufficient balance|authentication|rate.?limit|overloaded/i;
206:
207:/**
208: * A billing, auth or availability failure of the provider, not of the agent: status 401/402/403, or a message like
209: * "Insufficient Balance". `status` is null when only the message told. Null when the failure is something else.
210: * 429/5xx keep their own kinds (rate_limited, server_error) after retries; the runner treats those the same way.
211: */
212:export function providerErrorOf(j: Json | null, stderr: string, apiStatus: number | null): { status: number | null } | null {
213:  if (apiStatus !== null && PROVIDER_STATUSES.has(apiStatus)) return { status: apiStatus };
214:  if (apiStatus !== null) return null;
215:  const text = `${typeof j?.result === "string" ? j.result : ""}\n${stderr}`;
216:  return PROVIDER_MESSAGE.test(text) ? { status: null } : null;
217:}
218:
219:function errorKindOf(j: Json | null, x: Exec, apiStatus: number | null): HarnessErrorKind | null {
220:  if (x.timedOut) return "timeout";
221:  if (x.spawnError) return "spawn_failed";
222:  if (!j) return "unparseable_output";
223:  const subtype = String(j.subtype ?? "");
224:  // Auth failures come back as subtype "success" with is_error true: trust is_error, not subtype.
225:  if (!j.is_error && subtype === "success") return null;
226:  if (subtype === "error_max_turns") return "max_turns";
227:  if (/budget/i.test(subtype)) return "budget";
228:  if (apiStatus === 429) return "rate_limited";
229:  if (retryable(apiStatus)) return "server_error";
230:  if (providerErrorOf(j, x.err, apiStatus)) return "provider_unavailable";
231:  return "agent_error";
232:}
233:
234:/** The model that did the work: the costliest `modelUsage` entry (background calls use cheaper ones). */
235:export function resolvedModel(j: Json | null): { model: string | null; models: string[] } {
236:  const mu: Json = j?.modelUsage ?? {};
237:  const models = Object.keys(mu);
238:  const weight = (k: string) => Number(mu[k]?.costUSD ?? 0) * 1e9 + Number(mu[k]?.outputTokens ?? 0);
239:  const model = models.length ? models.reduce((a, b) => (weight(b) > weight(a) ? b : a)) : null;
240:  return { model, models };
241:}
242:
243:export function tokensOf(j: Json | null): HarnessTokens {
244:  const mu: Json | undefined = j?.modelUsage;
245:  if (mu && Object.keys(mu).length) {
246:    const sum = (k: string) => Object.values(mu).reduce((s: number, v: any) => s + (Number(v?.[k]) || 0), 0);
247:    return {
248:      input: sum("inputTokens"),
249:      output: sum("outputTokens"),
250:      cacheRead: sum("cacheReadInputTokens"),
251:      cacheWrite: sum("cacheCreationInputTokens"),
252:    };
253:  }
254:  const u: Json = j?.usage ?? {};
255:  return {
256:    input: Number(u.input_tokens) || 0,
257:    output: Number(u.output_tokens) || 0,
258:    cacheRead: Number(u.cache_read_input_tokens) || 0,
259:    cacheWrite: Number(u.cache_creation_input_tokens) || 0,
260:  };
261:}
262:
263:const num = (v: unknown): number | null => (typeof v === "number" && Number.isFinite(v) ? v : null);
264:const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
