234:/** The model that did the work: the costliest `modelUsage` entry (background calls use cheaper ones). */
235:export function resolvedModel(j: Json | null): { model: string | null; models: string[] } {
236:  const mu: Json = j?.modelUsage ?? {};
237:  const models = Object.keys(mu);
238:  const weight = (k: string) => Number(mu[k]?.costUSD ?? 0) * 1e9 + Number(mu[k]?.outputTokens ?? 0);
239:  const model = models.length ? models.reduce((a, b) => (weight(b) > weight(a) ? b : a)) : null;
240:  return { model, models };
241:}
