267:export async function runClaude(o: HarnessRunOptions): Promise<ClaudeHarnessResult> {
268:  const sandboxPath = resolve(o.sandboxPath);
269:  const outDir = resolve(o.outDir ?? `${sandboxPath}.out`);
270:  const args = claudeArgs(o);
271:  const bin = o.bin ?? "claude";
272:  const provider = isProviderRun(o.env);
273:  const res: ClaudeHarnessResult = {
274:    harness: HARNESS, sessionId: null, model: null, models: [], turns: null, durationMs: null, costUsd: null, reportedCostUsd: null,
275:    tokens: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 }, isError: true, errorKind: null, stopReason: null,
276:    transcriptPath: null, diff: null, setupSha: null, attempts: [], command: [bin, ...args],
277:  };
278:
279:  try {
280:    mkdirSync(outDir, { recursive: true });
281:    res.setupSha = swapRules(sandboxPath, o.rulesFile);
282:  } catch (e) {
283:    res.errorKind = "setup_failed";
284:    writeFileSync(join(outDir, "error.txt"), String(e));
285:    return res;
286:  }
287:
288:  const env = childEnv(o.env);
289:  const maxRetries = o.maxRetries ?? 2;
290:  let last: Json | null = null;
291:  const setupSha = res.setupSha;
292:  for (let n = 1; ; n++) {
293:    if (n > 1) {
294:      try {
295:        resetTo(sandboxPath, setupSha);
296:      } catch (e) {
297:        writeFileSync(join(outDir, "error.txt"), String(e));
298:        break; // keep the last attempt's verdict rather than run on a dirty sandbox
299:      }
300:    }
301:    const x = await exec(bin, args, sandboxPath, env, o.timeoutMs);
302:    const j = parseResult(x.out);
303:    const apiStatus = x.timedOut ? null : apiStatusOf(j, x.err);
304:    const errorKind = errorKindOf(j, x, apiStatus);
305:    const rawPath = join(outDir, `claude.attempt-${n}.json`);
306:    writeFileSync(rawPath, j ? JSON.stringify(j, null, 2) : JSON.stringify({ stdout: x.out, stderr: x.err.slice(-4000), spawnError: x.spawnError }, null, 2));
307:    const reported = num(j?.total_cost_usd);
308:    const t = tokensOf(j);
309:    let costUsd = reported;
310:    if (provider) {
311:      const counts = { input: t.input, output: t.output, cache_read: t.cacheRead, cache_write: t.cacheWrite };
312:      costUsd = j ? (priceDeepSeek(resolvedModel(j).model ?? o.model, counts, new Date())?.usd ?? null) : null;
313:    }
314:    res.attempts.push({ n, exitCode: x.code, timedOut: x.timedOut, wallMs: x.wallMs, isError: errorKind !== null, errorKind, apiStatus, rawPath, costUsd });
315:    if (costUsd !== null) res.costUsd = (res.costUsd ?? 0) + costUsd;
316:    if (reported !== null) res.reportedCostUsd = (res.reportedCostUsd ?? 0) + reported;
317:    res.tokens = { input: res.tokens.input + t.input, output: res.tokens.output + t.output, cacheRead: res.tokens.cacheRead + t.cacheRead, cacheWrite: res.tokens.cacheWrite + t.cacheWrite };
318:    last = j;
319:    res.isError = errorKind !== null;
320:    res.errorKind = errorKind;
321:    res.transcriptPath = rawPath;
322:    if (!(errorKind !== null && retryable(apiStatus) && n <= maxRetries)) break;
323:    await sleep((o.retryBaseMs ?? 2000) * 2 ** (n - 1));
