59:export class ForwardStore {
60:  readonly db: Database;
61:  constructor(path: string) {
62:    if (path !== ":memory:") mkdirSync(dirname(resolve(path)), { recursive: true });
63:    this.db = new Database(path, { create: true });
64:    this.db.exec(`CREATE TABLE IF NOT EXISTS forward_pairs (
65:      task_id TEXT PRIMARY KEY, setup_old TEXT NOT NULL, setup_new TEXT NOT NULL, pass_old INTEGER NOT NULL, pass_new INTEGER NOT NULL,
66:      cost_old REAL, cost_new REAL, merged TEXT, blind_labels TEXT NOT NULL, seed INTEGER NOT NULL, seq INTEGER NOT NULL)`);
67:    this.db.exec("CREATE TABLE IF NOT EXISTS forward_state (key TEXT PRIMARY KEY, value TEXT NOT NULL)");
68:    // Columns added by amendment 8; databases from earlier runs gain them as NULL.
69:    const have = new Set((this.db.query("PRAGMA table_info(forward_pairs)").all() as { name: string }[]).map((c) => c.name));
70:    for (const [col, type] of Object.entries(EXTRA_COLUMNS)) if (!have.has(col)) this.db.exec(`ALTER TABLE forward_pairs ADD COLUMN ${col} ${type}`);
71:  }
72:
73:  pairs(): ForwardPair[] {
74:    const rows = this.db.query("SELECT * FROM forward_pairs ORDER BY seq").all() as Record<string, unknown>[];
75:    const bool = (v: unknown) => (v === null || v === undefined ? null : v === 1);
76:    return rows.map((r) => ({
77:      task_id: r.task_id as string,
78:      setup_old: r.setup_old as string,
79:      setup_new: r.setup_new as string,
80:      pass_old: r.pass_old === 1,
81:      pass_new: r.pass_new === 1,
82:      cost_old: r.cost_old as number | null,
83:      cost_new: r.cost_new as number | null,
84:      merged: r.merged as "old" | "new" | null,
85:      blind_labels: JSON.parse(r.blind_labels as string),
86:      seed: r.seed as number,
87:      suite_pass_old: bool(r.suite_old),
88:      suite_pass_new: bool(r.suite_new),
89:      scope_ok_old: bool(r.scope_old),
90:      scope_ok_new: bool(r.scope_new),
91:      merged_reason: (r.merged_reason ?? null) as ForwardPair["merged_reason"],
92:      secondary: (r.secondary ?? null) as ForwardPair["secondary"],
93:    }));
94:  }
95:
96:  addPair(p: ForwardPair): void {
97:    const seq = (this.db.query("SELECT COUNT(*) AS n FROM forward_pairs").get() as { n: number }).n;
98:    this.db
99:      .query(
100:        `INSERT OR REPLACE INTO forward_pairs (task_id, setup_old, setup_new, pass_old, pass_new, cost_old, cost_new, merged, blind_labels, seed, seq,
101:          suite_old, suite_new, scope_old, scope_new, merged_reason, secondary) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`,
102:      )
103:      .run(p.task_id, p.setup_old, p.setup_new, +p.pass_old, +p.pass_new, p.cost_old, p.cost_new, p.merged, JSON.stringify(p.blind_labels), p.seed, seq, ...extraValues(p));
104:  }
105:
106:  /** Rewrites a recorded pair's merge outcome (remerge). The H1 fields, costs and seq are left as recorded. */
107:  updateMerge(p: ForwardPair): void {
108:    this.db
109:      .query("UPDATE forward_pairs SET suite_old=?, suite_new=?, scope_old=?, scope_new=?, merged_reason=?, secondary=?, merged=?, blind_labels=? WHERE task_id=?")
110:      .run(...extraValues(p), p.merged, JSON.stringify(p.blind_labels), p.task_id);
111:  }
112:
113:  getState(key: string): string | null {
114:    return (this.db.query("SELECT value FROM forward_state WHERE key = ?").get(key) as { value: string } | null)?.value ?? null;
115:  }
116:  setState(key: string, value: string): void {
