126:export interface StopRuleState {
127:  pairs: number;
128:  /** Discordant pairs NEW won (NEW passed, OLD failed) and lost. */
129:  won: number;
130:  lost: number;
131:  triggered: boolean;
132:}
133:
134:export function evaluateStopRule(pairs: ForwardPair[]): StopRuleState {
135:  const won = pairs.filter((p) => p.pass_new && !p.pass_old).length;
136:  const lost = pairs.filter((p) => !p.pass_new && p.pass_old).length;
137:  return { pairs: pairs.length, won, lost, triggered: pairs.length >= MIN_PAIRS && lost - won >= MIN_NET_LOSSES };
138:}
