235:async function gradeBranch(opts: {
236:  repo: string;
237:  base: string;
238:  head: string;
239:  hidden: HiddenTest[];
240:  owns: string[];
241:  testCmd?: string;
242:  scratch: string;
243:}): Promise<SideGrade> {
244:  const sandbox = await createSandbox(opts.repo, opts.base, { root: opts.scratch });
245:  try {
246:    const patch = runGit(opts.repo, ["diff", "--binary", opts.base, opts.head]);
247:    if (patch) {
248:      const pf = join(sandbox.path, "..", `${sandbox.path.split("/").at(-1)}.patch`);
249:      writeFileSync(pf, patch + "\n");
250:      runGit(sandbox.path, ["apply", "--binary", pf]);
251:      rmSync(pf, { force: true });
252:    }
253:    const preexistingTests = runGit(opts.repo, ["ls-tree", "-r", "--name-only", opts.base]).split("\n").filter((p) => p && isTestFile(p));
254:    const r = await grade({
255:      sandbox,
256:      hidden: opts.hidden,
257:      preexistingTests,
258:      touchedDirs: opts.owns.length ? opts.owns : undefined,
259:      testCmd: opts.testCmd,
260:    });
261:    return { pass: r.hiddenPass && r.suitePass && r.scopeOk, hiddenPass: r.hiddenPass, suitePass: r.suitePass, scopeOk: r.scopeOk };
262:  } finally {
263:    await destroySandbox(sandbox.path);
264:  }
265:}
