299:type Settled = Pick<ForwardPair, "blind_labels" | "merged" | "merged_reason" | "secondary" | "suite_pass_old" | "suite_pass_new" | "scope_ok_old" | "scope_ok_new">;
300:
301:/** Runs the blind judge when the policy needs it, picks the side to merge, merges it, and records why. */
302:async function settle(
303:  ctx: SettleContext,
304:  task: BacklogTask,
305:  seed: number,
306:  setups: Record<Side, string>,
307:  pass: Record<Side, boolean>,
308:  sides: Record<Side, SideState>,
309:): Promise<Settled> {
310:  const random = rng(seed);
311:  let labels = assignLabels(random);
312:  const eligible = { old: sides.old.suitePass && sides.old.scopeOk, new: sides.new.suitePass && sides.new.scopeOk };
313:  // Without amendment 8 the judge only breaks both-pass ties; with it, it also ranks two suite+scope-ok sides.
314:  const judgeOn = ctx.buildMerge ? eligible : pass;
315:  let preferred: Side | null = null;
316:  if (judgeOn.old && judgeOn.new) {
317:    const diffs = {
318:      old: runGit(ctx.repo, ["diff", sides.old.base, sides.old.head]),
319:      new: runGit(ctx.repo, ["diff", sides.new.base, sides.new.head]),
320:    };
321:    // A fresh stream from the same seed draws the same labels as above, so the logged seed reproduces them.
322:    const judged = await blindJudge(ctx.llm, task.body, diffs, rng(seed), [setups.old, setups.new]);
323:    labels = judged.labels;
324:    preferred = judged.preferred;
325:    ctx.log(`forward: ${task.id}: judge ${judged.verdict} (X=${labels.X}, Y=${labels.Y})`);
326:  }
327:  const choice: MergeChoice = chooseMerge(pass, preferred, random, ctx.buildMerge ? eligible : undefined);
328:  let merged = choice.merged;
329:  let reason: MergeReason = choice.reason;
330:  if (merged && !(await mergeBranch(ctx, task.id, sides[merged].branch, setups[merged]))) {
331:    merged = null;
332:    reason = "merge_failed";
333:  }
334:  const secondary = ctx.buildMerge ? secondaryOutcome(eligible, preferred) : null;
335:  ctx.log(
336:    `forward: ${task.id}: old ${pass.old ? "pass" : "fail"}, new ${pass.new ? "pass" : "fail"}, ${choice.reason}, merged ${merged ?? "none"}, seed ${seed}` +
337:      (secondary ? `; secondary (exploratory) ${secondary}` : ""),
338:  );
339:  return {
340:    blind_labels: labels,
341:    merged,
342:    merged_reason: reason,
343:    secondary,
344:    suite_pass_old: sides.old.suitePass,
345:    suite_pass_new: sides.new.suitePass,
346:    scope_ok_old: sides.old.scopeOk,
347:    scope_ok_new: sides.new.scopeOk,
348:  };
349:}
