  };
  const costs = (db: string) => {
    const d = new Database(db, { readonly: true });
    const row = d.query("SELECT cost_old, cost_new FROM forward_pairs WHERE task_id = 'F01'").get() as { cost_old: number; cost_new: number };
    d.close();
